/* Matematica – Fondamenti – version italienne, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"Mod. 1a","t":"Lunghezze e masse","g":"Convertire lunghezze e masse con le tabelle delle unità","col":"teal","ic":"ruler","ch":[{"k":"qcm","img":"longueurs","q":"Nella tabella delle lunghezze, che cosa si fa a ogni passo verso un’unità più piccola (verso destra)?","a":["Si moltiplica per 10","Si moltiplica per 100","Si divide per 10","Si moltiplica per 1’000"],"ex":"km → hm → dam → m → dm → cm → mm: ogni passo verso destra = × 10, ogni passo verso sinistra = ÷ 10.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"num","q":"Converta 3.5 km in metri.","n":3500,"tol":0,"u":"m","ex":"km → m = 3 passi verso destra: 3.5 × 10 × 10 × 10 = 3’500 m.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"num","q":"Converta 2.4 m in centimetri.","n":240,"tol":0,"u":"cm","ex":"m → cm = 2 passi verso destra: 2.4 × 100 = 240 cm.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"num","q":"Converta 1’250 mm in centimetri.","n":125,"tol":0,"u":"cm","ex":"mm → cm = 1 passo verso sinistra: 1’250 ÷ 10 = 125 cm.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"qcm","q":"Una paletta EUR è lunga 1’200 mm. Quanto fa in metri?","a":["1.2 m","12 m","0.12 m","120 m"],"ex":"mm → m = 3 passi verso sinistra: 1’200 ÷ 1’000 = 1.2 m.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"case","s":"Il magazziniere della Stockalp SA sistema cartoni larghi 35 cm uno accanto all’altro su un ripiano di scaffale lungo 4.2 m.","q":"Quanti cartoni stanno sulla lunghezza del ripiano?","a":["12 cartoni","120 cartoni","14 cartoni","1 cartone"],"ex":"Tutto nella stessa unità: 4.2 m = 420 cm. 420 ÷ 35 = 12 cartoni.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"order","q":"Metta in ordine queste unità di lunghezza dalla più grande alla più piccola.","a":["km","dam","m","cm","mm"],"ex":"Ordine della tabella: km, hm, dam, m, dm, cm, mm.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"match","q":"Abbini ogni unità alla sua equivalenza.","p":[["1 km","1’000 m"],["1 m","100 cm"],["1 cm","10 mm"],["1 dam","10 m"]],"ex":"Ogni passo della tabella vale × 10: 1 m = 10 dm = 100 cm = 1’000 mm.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"tf","q":"Per convertire 5 mm in metri si moltiplica per 1’000.","v":false,"ex":"Falso: mm → m va verso un’unità più grande, quindi si divide: 5 ÷ 1’000 = 0.005 m.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"tf","q":"1 hg (ettogrammo) vale 10 g.","v":false,"ex":"Falso: 1 hg = 100 g. È 1 dag (decagrammo) che vale 10 g.","ref":"Modulo 1 · Conversioni di masse"},{"k":"qcm","q":"Quanti chilogrammi ci sono in 1 tonnellata?","a":["1’000 kg","100 kg","10 kg","10’000 kg"],"ex":"1 t = 1’000 kg. Nella tabella t, q, kg: 1 t = 10 q e 1 q = 100 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"qcm","q":"Quanto vale un quintale (q)?","a":["100 kg","10 kg","1’000 kg","50 kg"],"ex":"Il quintale si trova tra la tonnellata e il chilogrammo: 1 q = 100 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"num","q":"Converta 2.75 t in chilogrammi.","n":2750,"tol":0,"u":"kg","ex":"t → kg: × 1’000. 2.75 × 1’000 = 2’750 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"num","q":"Converta 2’500 dag in chilogrammi.","n":25,"tol":0,"u":"kg","ex":"dag → kg = 2 passi verso sinistra (dag → hg → kg): 2’500 ÷ 10 ÷ 10 = 25 kg. Errore frequente: rispondere 250 kg (un solo passo).","ref":"Modulo 1 · Conversioni di masse"},{"k":"case","s":"Un camion della TransRhône consegna tre lotti: 600 kg di viti, 1.4 t di lamiere e 2’500 dag di etichette. L’autista deve annotare la massa totale sulla bolla.","q":"Quale massa totale deve scrivere?","a":["2’025 kg","2’250 kg","2’000 kg","4’500 kg"],"ex":"Si converte tutto in kg: 600 kg + 1’400 kg + 25 kg = 2’025 kg. 2’500 dag = 25 kg, non 250 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"fill","q":"Per convertire grammi in chilogrammi si ___ per 1’000.","a":["divide","moltiplica","somma","sottrae"],"ex":"g → kg: verso un’unità più grande si divide. 3’400 g = 3.4 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"sort","q":"Classifichi ogni massa: meno di 1 kg oppure 1 kg e più?","c":["Meno di 1 kg","1 kg e più"],"it":[["950 g",0],["12 hg",1],["80 dag",0],["0.001 t",1],["1’500’000 mg",1],["9 hg",0]],"ex":"12 hg = 1.2 kg; 80 dag = 0.8 kg; 0.001 t = 1 kg; 1’500’000 mg = 1.5 kg; 9 hg = 0.9 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"odd","q":"Trovi l’intruso: quale di queste lunghezze NON è uguale a 1.5 m?","a":["15 cm","150 cm","1’500 mm","15 dm"],"ex":"1.5 m = 15 dm = 150 cm = 1’500 mm. 15 cm valgono solo 0.15 m.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"case","s":"Un carrello elevatore ha una portata di 1.2 t. Il carrellista deve sollevare una paletta di 850 kg sulla quale sono stati aggiunti 3 cartoni da 120 kg.","q":"Può sollevare questo carico?","a":["No: 1’210 kg, superamento di 10 kg","Sì: 1’210 kg, restano 10 kg","Sì: 850 kg sono sotto 1.2 t","No: 1’210 kg superano 12 t"],"ex":"1.2 t = 1’200 kg. 850 + 3 × 120 = 1’210 kg > 1’200 kg: superamento di 10 kg. Bisogna togliere un cartone.","ref":"Modulo 1 · Conversioni di masse"},{"k":"case","s":"Alla postazione di spedizione, un preparatore imballa 18 colli identici da 750 g per lo stesso cliente.","q":"Qual è la massa totale della spedizione?","a":["13.5 kg","135 kg","1.35 kg","13’500 kg"],"ex":"18 × 750 g = 13’500 g = 13.5 kg (÷ 1’000).","ref":"Modulo 1 · Conversioni di masse"},{"k":"multi","q":"Quali masse valgono esattamente 2 kg?","good":["2’000 g","20 hg","200 dag","2’000’000 mg"],"bad":["0.2 t","20’000 mg"],"ex":"2 kg = 20 hg = 200 dag = 2’000 g = 2’000’000 mg. 0.2 t = 200 kg; 20’000 mg = 20 g.","ref":"Modulo 1 · Conversioni di masse"},{"k":"case","s":"Per raggiungere il magazzino annesso, il carrellista percorre 0.6 km sulla strada di servizio, poi ancora 450 m nel cortile.","q":"Che distanza percorre?","a":["1’050 m","1’050 km","456 m","0.105 km"],"ex":"Si converte prima di sommare: 0.6 km = 600 m. 600 + 450 = 1’050 m.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"case","s":"Tra la banchina di ricevimento e la zona di stoccaggio ci sono 85 m. Stamattina il carrellista ha fatto 12 andate e ritorni con il suo carrello.","q":"Che distanza ha percorso?","a":["2.04 km","1.02 km","20.4 km","0.204 km"],"ex":"Un’andata e ritorno = 2 × 85 = 170 m. 12 × 170 = 2’040 m = 2.04 km.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"case","s":"Un camion deve passare sotto la porta di un magazzino alta 3.8 m. Il carico: 3 palette sovrapposte di 1’350 mm ciascuna, appoggiate sul pianale.","q":"Il carico (senza il camion) supera già l’altezza della porta?","a":["Sì: 4.05 m > 3.8 m","No: 4.05 m < 3.8 m","No: 1’350 mm < 3.8 m","Sì: 4’050 m > 3.8 m"],"ex":"3 × 1’350 = 4’050 mm = 4.05 m. È più di 3.8 m: bisogna disimpilare.","ref":"Modulo 1 · Conversioni di lunghezze"},{"k":"case","s":"Per un ordine sono stati preparati 250 rotoli di film estensibile da 2.4 kg ciascuno. Il trasportatore chiede la massa in tonnellate.","q":"Quale massa comunica?","a":["0.6 t","6 t","0.06 t","60 t"],"ex":"250 × 2.4 = 600 kg. 600 ÷ 1’000 = 0.6 t.","ref":"Modulo 1 · Conversioni di masse"},{"k":"case","s":"La bolla di consegna indica tre colli: 12.5 kg, 8’400 g e 95 hg. Deve controllare la massa totale.","q":"Qual è la massa totale?","a":["30.4 kg","125.9 kg","3.04 kg","304 kg"],"ex":"8’400 g = 8.4 kg; 95 hg = 9.5 kg. 12.5 + 8.4 + 9.5 = 30.4 kg.","ref":"Modulo 1 · Conversioni di masse"},{"k":"num","q":"Converta 4’500 kg in quintali.","n":45,"tol":0,"u":"q","ex":"kg → q: ÷ 100. 4’500 ÷ 100 = 45 q.","ref":"Modulo 1 · Conversioni di masse"},{"k":"tf","q":"1 dam (decametro) vale 10 m.","v":true,"ex":"Vero: km, hm, dam, m. 1 dam = 10 m; 1 hm = 100 m.","ref":"Modulo 1 · Conversioni di lunghezze"}]},{"code":"Mod. 1b","t":"Forza e peso","g":"Calcolare il peso (forza in newton) di un carico a partire dalla sua massa, e viceversa","col":"indigo","ic":"weight","ch":[{"k":"qcm","q":"In quale unità si esprime una forza, per esempio il peso di un carico?","a":["In newton (N)","In chilogrammi (kg)","In joule (J)","In pascal (Pa)"],"ex":"La massa si esprime in kg; il peso è una forza e si esprime in newton (N).","ref":"Modulo 1 · Forza e peso"},{"k":"tf","q":"La massa (in kg) e il peso (in N) sono due grandezze diverse.","v":true,"ex":"Vero: la massa è la quantità di materia (kg); il peso è la forza esercitata da questa massa (N).","ref":"Modulo 1 · Forza e peso"},{"k":"fill","q":"Il peso di un carico si calcola con la formula F = m × ___ (in N/kg).","a":["9.81","0.981","98.1","3.6"],"ex":"F (N) = m (kg) × 9.81. In pratica, per stimare si arrotonda spesso a 10.","ref":"Modulo 1 · Forza e peso"},{"k":"num","q":"Con l’arrotondamento pratico g ≈ 10 N/kg, qual è il peso di una cassa di 50 kg?","n":500,"tol":0,"u":"N","ex":"50 × 10 = 500 N (calcolo esatto: 50 × 9.81 = 490.5 N).","ref":"Modulo 1 · Forza e peso"},{"k":"qcm","q":"Qual è il peso esatto di un cartone di 20 kg (g = 9.81 N/kg)?","a":["196.2 N","1’962 N","2.04 N","19.62 N"],"ex":"20 × 9.81 = 196.2 N.","ref":"Modulo 1 · Forza e peso"},{"k":"num","q":"Quanti newton vale 1 kN?","n":1000,"tol":0,"u":"N","ex":"Kilo = 1’000: 1 kN = 1’000 N.","ref":"Modulo 1 · Forza e peso"},{"k":"num","q":"Converta 2.5 kN in newton.","n":2500,"tol":0,"u":"N","ex":"2.5 × 1’000 = 2’500 N.","ref":"Modulo 1 · Forza e peso"},{"k":"qcm","q":"Un carico esercita un peso di 981 N. Qual è la sua massa?","a":["100 kg","98.1 kg","9’624 kg","10 kg"],"ex":"m = F ÷ 9.81 = 981 ÷ 9.81 = 100 kg. Errore frequente: dividere per 10 invece che per 9.81, il che dà 98.1 kg.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Il transpallet manuale dell’officina ha una portata di 2’000 kg. Il dinamometro indica che la paletta da spostare esercita una forza di 17’658 N.","q":"Il transpallet può spostarla?","a":["Sì: 1’800 kg, restano 200 kg","No: 17’658 kg superano 2’000 kg","Sì: solo 176.58 kg","No: 1’800 kg superano 2’000 kg"],"ex":"m = 17’658 ÷ 9.81 = 1’800 kg ≤ 2’000 kg: è possibile, con un margine di 200 kg.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Un ripiano di scaffale sopporta al massimo 3 kN. Un preparatore vuole appoggiarvi 4 cartoni da 80 kg. Stima il peso con g ≈ 10 N/kg.","q":"Può appoggiare i 4 cartoni?","a":["No: 3’200 N superano 3’000 N","Sì: 320 N restano sotto 3 kN","Sì: 3’200 N restano sotto 3 kN","No: 320 kg superano 3 kg"],"ex":"4 × 80 = 320 kg → 320 × 10 = 3’200 N = 3.2 kN > 3 kN. Se ne possono mettere al massimo 3.","ref":"Modulo 1 · Forza e peso"},{"k":"match","q":"Abbini ogni massa al suo peso approssimativo (g ≈ 10 N/kg).","p":[["1 kg","≈ 10 N"],["50 kg","≈ 500 N"],["100 kg","≈ 1 kN"],["1 t","≈ 10 kN"]],"ex":"Peso ≈ massa × 10: 1 t = 1’000 kg → ≈ 10’000 N = 10 kN.","ref":"Modulo 1 · Forza e peso"},{"k":"order","q":"Metta in ordine il calcolo del peso di un carico indicato in tonnellate.","a":["Convertire la massa in kg","Moltiplicare per 9.81","Scrivere il risultato in N","Convertire in kN se necessario (÷ 1’000)"],"ex":"Esempio: 1.5 t = 1’500 kg; 1’500 × 9.81 = 14’715 N = 14.715 kN.","ref":"Modulo 1 · Forza e peso"},{"k":"sort","q":"Classifichi ogni valore: massa o forza (peso)?","c":["Massa","Forza (peso)"],"it":[["1.2 t",0],["450 kg",0],["12 kN",1],["981 N",1],["750 g",0],["4’000 N",1]],"ex":"t, kg e g sono unità di massa; N e kN sono unità di forza.","ref":"Modulo 1 · Forza e peso"},{"k":"odd","q":"Trovi l’intruso: quale NON è un’unità di forza?","a":["kg","N","kN","daN"],"ex":"Il chilogrammo è un’unità di massa. N, kN e daN (decanewton) misurano una forza.","ref":"Modulo 1 · Forza e peso"},{"k":"tf","q":"Sulla Luna la massa di un collo è più piccola che sulla Terra.","v":false,"ex":"Falso: la massa non cambia. È il peso (la forza) che cambia, perché l’attrazione è più debole.","ref":"Modulo 1 · Forza e peso"},{"k":"num","q":"Con g ≈ 10 N/kg, qual è il peso di una cassa di 1.5 t, in kN?","n":15,"tol":0,"u":"kN","ex":"1.5 t = 1’500 kg → 1’500 × 10 = 15’000 N = 15 kN.","ref":"Modulo 1 · Forza e peso"},{"k":"qcm","q":"Qual è il peso esatto di una paletta di 600 kg?","a":["5’886 N","6’000 N","61.2 N","588.6 N"],"ex":"600 × 9.81 = 5’886 N. 6’000 N è la stima con g ≈ 10.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Un paranco dell’officina sopporta al massimo 5 kN. Il meccanico deve sollevare un motore di 450 kg per appoggiarlo su una paletta.","q":"Il paranco è adatto?","a":["Sì: 4’414.5 N < 5’000 N","No: 4’414.5 N > 5’000 N","No: 450 kg > 5 kg","Sì: 45.9 N < 5 kN"],"ex":"F = 450 × 9.81 = 4’414.5 N, cioè 4.41 kN: è sotto il limite di 5 kN.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"La scheda tecnica di un apparecchio di sollevamento indica una forza di sollevamento massima di 25 kN. Il caposquadra vuole conoscere la massa massima.","q":"Quale massa massima si può sollevare?","a":["Circa 2’548 kg","Circa 245 kg","Circa 25 kg","Circa 245’250 kg"],"ex":"25 kN = 25’000 N. m = 25’000 ÷ 9.81 ≈ 2’548 kg (circa 2.5 t).","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Un collega calcola il peso di una paletta di 300 kg e scrive sul suo foglio: «300 ÷ 9.81 = 30.6 N».","q":"Che cosa gli risponde?","a":["Sbagliato: bisogna moltiplicare, 2’943 N","Giusto: il peso vale 30.6 N","Sbagliato: bisogna dividere per 10","Giusto, ma va scritto in kg"],"ex":"Peso = massa × 9.81 = 300 × 9.81 = 2’943 N. Si divide solo per passare da una forza a una massa.","ref":"Modulo 1 · Forza e peso"},{"k":"num","q":"Un carico pesa 3’000 N. Con g ≈ 10 N/kg, qual è la sua massa?","n":300,"tol":0,"u":"kg","ex":"m ≈ 3’000 ÷ 10 = 300 kg (esatto: 3’000 ÷ 9.81 ≈ 305.8 kg).","ref":"Modulo 1 · Forza e peso"},{"k":"multi","q":"Quali affermazioni sono giuste?","good":["Il peso si esprime in newton","1 kg pesa circa 10 N","1 kN = 1’000 N"],"bad":["1 N = 1 kg","Il peso si calcola dividendo la massa per 9.81"],"ex":"Peso (N) = massa (kg) × 9.81; 1 kg pesa 9.81 N, non 1 N.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Ogni livello di uno scaffale sopporta 5 kN. Vi si stoccano cartoni da 40 kg. Per il calcolo l’azienda usa g ≈ 10 N/kg.","q":"Quanti cartoni si possono appoggiare al massimo per livello?","a":["12 cartoni","13 cartoni","125 cartoni","1 cartone"],"ex":"1 cartone ≈ 40 × 10 = 400 N. 5’000 ÷ 400 = 12.5 → si arrotonda per difetto: 12 cartoni.","ref":"Modulo 1 · Forza e peso"},{"k":"qcm","q":"A quale massa corrisponde una forza di 4’905 N?","a":["500 kg","48’118 kg","490.5 kg","50 kg"],"ex":"m = 4’905 ÷ 9.81 = 500 kg.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Un carroponte è autorizzato fino a 2 t. Il sensore del carico sospeso indica 22 kN.","q":"Il carico è ammesso?","a":["No: circa 2’243 kg > 2’000 kg","Sì: circa 224 kg < 2’000 kg","Sì: 22 kN restano sotto il limite di 2 t","No: 22 kN corrispondono a 22 t"],"ex":"22 kN = 22’000 N. m = 22’000 ÷ 9.81 ≈ 2’243 kg: è più di 2’000 kg. Non si solleva.","ref":"Modulo 1 · Forza e peso"},{"k":"case","s":"Un container di 1’200 kg è appoggiato sul pavimento di una piattaforma di carico. Il responsabile della sicurezza vuole la forza esercitata in kN.","q":"Quale forza esercita il container?","a":["11.77 kN","11’772 kN","122.32 kN","1.22 kN"],"ex":"1’200 × 9.81 = 11’772 N = 11.77 kN.","ref":"Modulo 1 · Forza e peso"}]},{"code":"Mod. 1c","t":"Percentuali","g":"Calcolare una parte, un tasso e un valore dopo un aumento o uno sconto","col":"violet","ic":"percent","ch":[{"k":"qcm","q":"A quale frazione corrisponde il 25 %?","a":["1/4","1/25","2/5","1/2"],"ex":"25 % = 25/100 = 1/4.","ref":"Modulo 1 · Percentuali"},{"k":"num","q":"Calcoli il 15 % di 400 colli.","n":60,"tol":0,"u":"colli","ex":"Parte = totale × tasso ÷ 100 = 400 × 15 ÷ 100 = 60 colli.","ref":"Modulo 1 · Percentuali"},{"k":"num","q":"Calcoli il 10 % di CHF 2’500.","n":250,"tol":0,"u":"CHF","ex":"2’500 × 10 ÷ 100 = CHF 250.","ref":"Modulo 1 · Percentuali"},{"k":"num","q":"Su 80 ordini, 12 sono consegnati in ritardo. Qual è la percentuale di ritardi?","n":15,"tol":0,"u":"%","ex":"Tasso = parte ÷ totale × 100 = 12 ÷ 80 × 100 = 15 %.","ref":"Modulo 1 · Percentuali"},{"k":"fill","q":"Tasso (%) = parte ÷ ___ × 100.","a":["totale","parte","tasso","sconto"],"ex":"Si divide la parte per il totale, poi si moltiplica per 100.","ref":"Modulo 1 · Percentuali"},{"k":"qcm","q":"Come si scrive 4.5 % sotto forma di numero decimale?","a":["0.045","0.45","4.5","0.0045"],"ex":"4.5 % = 4.5 ÷ 100 = 0.045. In una risposta si scrive il tasso con il segno %: 4.5 %.","ref":"Modulo 1 · Percentuali"},{"k":"match","q":"Abbini ogni percentuale al suo valore.","p":[["50 %","1/2"],["25 %","1/4"],["10 %","0.1"],["75 %","3/4"]],"ex":"Percentuale ÷ 100 = numero decimale.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"La Logibois ordina materiale per CHF 3’000. Il fornitore concede uno sconto del 12 %, poi fattura CHF 120 di spese di trasporto.","q":"Qual è il totale da pagare?","a":["CHF 2’760.00","CHF 2’640.00","CHF 2’745.60","CHF 3’108.00"],"ex":"Prima lo sconto: 3’000 × 0.88 = 2’640. Poi le spese: 2’640 + 120 = CHF 2’760.00.","ref":"Modulo 3 · Problemi serie 2"},{"k":"num","q":"Qual è l’importo dello sconto del 12 % su un ordine di CHF 3’000?","n":360,"tol":0,"u":"CHF","ex":"3’000 × 12 ÷ 100 = CHF 360.","ref":"Modulo 3 · Problemi serie 2"},{"k":"case","s":"Il magazzino conteneva 1’200 cartoni di un articolo. Durante la settimana è stato spedito il 35 % dello stock.","q":"Quanti cartoni restano?","a":["780 cartoni","420 cartoni","1’165 cartoni","835 cartoni"],"ex":"Spedito: 1’200 × 0.35 = 420. Resto: 1’200 − 420 = 780 cartoni (oppure 1’200 × 0.65).","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Durante l’inventario il magazziniere constata 6 differenze su 240 ubicazioni controllate. Il responsabile vuole il tasso d’errore.","q":"Qual è il tasso d’errore?","a":["2.5 %","0.025 %","40 %","6 %"],"ex":"6 ÷ 240 × 100 = 2.5 %.","ref":"Modulo 1 · Percentuali"},{"k":"tf","q":"Un aumento del 10 % seguito da una diminuzione del 10 % riporta esattamente al prezzo di partenza.","v":false,"ex":"Falso: 100 × 1.1 = 110; 110 × 0.9 = 99. La diminuzione si calcola su 110, non su 100.","ref":"Modulo 1 · Percentuali"},{"k":"order","q":"Metta in ordine il calcolo di una fattura con sconto e spese di trasporto.","a":["Calcolare lo sconto sul prezzo iniziale","Sottrarre lo sconto dal prezzo iniziale","Aggiungere le spese di trasporto","Controllare che il totale sia plausibile"],"ex":"Lo sconto si applica al prezzo della merce, prima di aggiungere le spese.","ref":"Modulo 3 · Problemi serie 2"},{"k":"sort","q":"Classifichi ogni coefficiente: aumento o diminuzione?","c":["Aumento","Diminuzione"],"it":[["× 1.08",0],["× 0.85",1],["× 1.2",0],["× 0.97",1],["× 1.081",0],["× 0.5",1]],"ex":"Maggiore di 1: aumento (1.08 = + 8 %). Minore di 1: diminuzione (0.85 = − 15 %).","ref":"Modulo 1 · Percentuali"},{"k":"odd","q":"Trovi l’intruso: quale di questi valori NON è uguale al 20 %?","a":["0.02","0.2","1/5","20/100"],"ex":"20 % = 20/100 = 0.2 = 1/5. 0.02 = 2 %.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Un cliente chiede il prezzo IVA inclusa di un articolo venduto a CHF 200.00 IVA esclusa. L’aliquota normale dell’IVA in Svizzera è dell’8.1 %.","q":"Qual è il prezzo IVA inclusa?","a":["CHF 216.20","CHF 215.40","CHF 208.10","CHF 183.80"],"ex":"Prezzo IVA inclusa = prezzo IVA esclusa × (1 + aliquota) = 200 × 1.081 = CHF 216.20. Non nel materiale del corso: il corso usa ancora il 7.7 %, ma l’aliquota normale è dell’8.1 % dal 1° gennaio 2024.","ref":"Modulo 3 · Problemi serie 3"},{"k":"num","q":"Un camion da 24 posti paletta è riempito al 75 %. Quante palette contiene?","n":18,"tol":0,"u":"palette","ex":"24 × 75 ÷ 100 = 18 palette.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Il fornitore di cartoni annuncia un aumento del 5 % dal 1° gennaio. Finora un lotto costava CHF 80.00.","q":"Quale sarà il nuovo prezzo del lotto?","a":["CHF 84.00","CHF 85.00","CHF 80.05","CHF 76.00"],"ex":"80 × 1.05 = CHF 84.00.","ref":"Modulo 1 · Percentuali"},{"k":"qcm","q":"Quanto fa il 18 % di 350?","a":["63","6.3","19.4","630"],"ex":"350 × 18 ÷ 100 = 63.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Una fattura di CHF 1’850.00 concede il 2 % di sconto se è pagata entro 10 giorni. La contabilità paga in tempo.","q":"Quale importo paga?","a":["CHF 1’813.00","CHF 1’848.00","CHF 1’480.00","CHF 1’887.00"],"ex":"1’850 × 0.98 = CHF 1’813.00 (sconto: CHF 37.00).","ref":"Modulo 1 · Percentuali"},{"k":"num","q":"90 palette rappresentano il 30 % dello stock. Quante palette conta lo stock totale?","n":300,"tol":0,"u":"palette","ex":"Totale = parte × 100 ÷ tasso = 90 × 100 ÷ 30 = 300 palette.","ref":"Modulo 1 · Percentuali"},{"k":"multi","q":"Quali calcoli danno il prezzo dopo uno sconto del 20 %?","good":["Prezzo × 0.8","Prezzo − Prezzo × 0.2","Prezzo × 80 ÷ 100"],"bad":["Prezzo × 1.2","Prezzo − 20"],"ex":"Sconto del 20 %: resta l’80 % del prezzo, quindi × 0.8.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Su 500 colli consegnati il mese scorso dal trasportatore, il 2 % è arrivato danneggiato. Il responsabile prepara il reclamo.","q":"Quanti colli sono danneggiati?","a":["10 colli","2 colli","25 colli","100 colli"],"ex":"500 × 2 ÷ 100 = 10 colli.","ref":"Modulo 1 · Percentuali"},{"k":"tf","q":"L’1 % di 1’000 kg vale 10 kg.","v":true,"ex":"Vero: 1’000 × 1 ÷ 100 = 10 kg.","ref":"Modulo 1 · Percentuali"},{"k":"case","s":"Il magazzino conta 800 ubicazioni per palette. Oggi 640 sono occupate. Il direttore vuole il tasso d’occupazione.","q":"Qual è il tasso d’occupazione?","a":["80 %","0.8 %","64 %","125 %"],"ex":"640 ÷ 800 × 100 = 80 %.","ref":"Modulo 1 · Percentuali"},{"k":"qcm","q":"La calcolatrice mostra 0.1 come risultato di un tasso. Quale percentuale rappresenta?","a":["10 %","1 %","0.1 %","100 %"],"ex":"0.1 × 100 = 10 %. Pensi a moltiplicare per 100 per scrivere il risultato in %.","ref":"Modulo 1 · Percentuali"}]},{"code":"Mod. 2a","t":"Superfici e volumi","g":"Calcolare e convertire superfici e volumi utili in magazzino","col":"coral","ic":"cube","ch":[{"k":"qcm","q":"Quale formula dà la superficie di un rettangolo?","a":["Lunghezza × larghezza","Lunghezza + larghezza","2 × (lunghezza + larghezza)","Lunghezza ÷ larghezza"],"ex":"Superficie = L × l. 2 × (L + l) dà il perimetro (il contorno), non la superficie.","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"num","q":"Qual è la superficie di un magazzino di 50 m per 24 m?","n":1200,"tol":0,"u":"m²","ex":"50 × 24 = 1’200 m².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"qcm","q":"Quale superficie al suolo occupa una paletta EUR di 1.2 m × 0.8 m?","a":["0.96 m²","9.60 m²","2.00 m²","4.00 m²"],"ex":"1.2 × 0.8 = 0.96 m².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"case","s":"Il responsabile della Stockalp SA prepara una zona per 20 palette EUR (1.2 m × 0.8 m) appoggiate a terra, senza impilare e senza contare i corridoi.","q":"Quale superficie serve almeno?","a":["19.2 m²","20 m²","40 m²","1.92 m²"],"ex":"1 paletta: 0.96 m². 20 × 0.96 = 19.2 m².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"num","q":"Quanti dm² ci sono in 1 m²?","n":100,"tol":0,"u":"dm²","ex":"Per le superfici, ogni passo della tabella vale × 100: 1 m² = 100 dm².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"num","q":"Converta 3.2 m² in cm².","n":32000,"tol":0,"u":"cm²","ex":"m² → cm² = 2 passi: 3.2 × 100 × 100 = 32’000 cm².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"qcm","q":"Converta 45’000 mm² in m².","a":["0.045 m²","0.450 m²","0.0045 m²","4.500 m²"],"ex":"mm² → m² = 3 passi verso sinistra: 45’000 ÷ 100 ÷ 100 ÷ 100 = 0.045 m². Attenzione: l’esempio del corso indica 0.45 m², è un errore.","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"tf","q":"Nella tabella delle superfici, ogni passo da un’unità alla successiva vale × 100 o ÷ 100.","v":true,"ex":"Vero: 1 m² = 100 dm² = 10’000 cm². Per le lunghezze è × 10; per i volumi × 1’000.","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"tf","q":"Nella tabella dei volumi, ogni passo da un’unità alla successiva vale × 1’000’000’000.","v":false,"ex":"Falso: ogni passo vale × 1’000 (1 m³ = 1’000 dm³). Il «trucco» del corso che parla di 1 miliardo per passo è un errore.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"num","q":"Quanti litri contiene 1 m³?","n":1000,"tol":0,"u":"L","ex":"1 m³ = 1’000 dm³ e 1 dm³ = 1 L, quindi 1 m³ = 1’000 L.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"num","q":"Converta 2.5 m³ in litri.","n":2500,"tol":0,"u":"L","ex":"2.5 × 1’000 = 2’500 L.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"qcm","q":"Converta 4’800 cm³ in litri.","a":["4.8 L","48 L","0.48 L","480 L"],"ex":"4’800 cm³ ÷ 1’000 = 4.8 dm³ = 4.8 L.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","s":"Lo spedizioniere deve comunicare il volume utile di un container il cui interno misura 6 m di lunghezza, 2.5 m di larghezza e 2.7 m di altezza.","q":"Quale volume comunica?","a":["40.5 m³","11.2 m³","15.0 m³","405 m³"],"ex":"V = 6 × 2.5 × 2.7 = 40.5 m³.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","s":"Bisogna sistemare fusti da 210 L in uno spazio di stoccaggio di 2.5 m³. Si conta solo il volume e un fusto non si divide.","q":"Quanti fusti interi si possono mettere al massimo?","a":["11 fusti","12 fusti","84 fusti","1 fusto"],"ex":"2.5 m³ = 2’500 L. 2’500 ÷ 210 = 11.9 → si arrotonda per difetto: 11 fusti.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","img":"zone","s":"Una zona di stoccaggio misura 6 m per 4 m. Vi si appoggiano palette EUR di 1.2 m × 0.8 m, tutte nello stesso senso, senza corridoio.","q":"Quante palette si possono appoggiare a terra?","a":["25 palette","24 palette","30 palette","20 palette"],"ex":"6 ÷ 1.2 = 5 palette sulla lunghezza; 4 ÷ 0.8 = 5 sulla larghezza. 5 × 5 = 25 palette (anche 24 m² ÷ 0.96 m² = 25).","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"num","q":"Quanti cartoni da 0.05 m³ si possono stoccare in 15 m³ (contando solo il volume)?","n":300,"tol":0,"u":"cartoni","ex":"15 ÷ 0.05 = 300 cartoni.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"qcm","q":"Qual è il volume di una paletta carica di 1.2 m × 0.8 m × 1.7 m?","a":["1.632 m³","3.7 m³","0.96 m³","16.32 m³"],"ex":"1.2 × 0.8 × 1.7 = 1.632 m³.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"match","q":"Abbini ogni unità alla sua equivalenza.","p":[["1 m²","100 dm²"],["1 m³","1’000 L"],["1 L","1 dm³"],["1 cm²","100 mm²"]],"ex":"Superfici: × 100 per passo. Volumi: × 1’000 per passo. 1 L = 1 dm³.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"sort","q":"Classifichi: superficie o volume?","c":["Superficie","Volume"],"it":[["m²",0],["m³",1],["L",1],["cm²",0],["Ingombro a terra di una paletta",0],["Capacità di una cisterna",1]],"ex":"Superficie: 2 dimensioni (m², cm²). Volume: 3 dimensioni (m³, L).","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"order","q":"Metta in ordine queste unità di superficie dalla più grande alla più piccola.","a":["km²","dam²","m²","cm²","mm²"],"ex":"km², hm², dam², m², dm², cm², mm².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"odd","q":"Trovi l’intruso: quale NON è un’unità di volume?","a":["m²","m³","L","dm³"],"ex":"m² misura una superficie. m³, L e dm³ misurano un volume.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","s":"Una paletta carica ha un volume di 1.44 m³ e occupa 0.96 m² a terra. Il magazziniere vuole conoscerne l’altezza per scegliere un’ubicazione.","q":"Qual è la sua altezza?","a":["1.5 m","1.38 m","2.4 m","0.67 m"],"ex":"Altezza = volume ÷ superficie = 1.44 ÷ 0.96 = 1.5 m.","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Uno scaffale porta-palette è profondo 1.2 m e lungo 12 m. Il responsabile vuole sapere quale superficie a terra occupa.","q":"Quale superficie occupa?","a":["14.4 m²","13.2 m²","26.4 m²","1.44 m²"],"ex":"1.2 × 12 = 14.4 m².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"case","s":"Una zona ha 12 m² a terra ed è alta 2.2 m. Si vogliono stoccare 9 palette di 0.96 m² e alte 1.67 m, impilate 2 a 2.","q":"Che cosa risponde?","a":["Non impilate, ma a terra ci stanno tutte e 9","Sì: bastano 5 ubicazioni impilate","No: le 9 palette non ci stanno","Sì, impilandole piuttosto 3 a 3"],"ex":"Impilate: 2 × 1.67 = 3.34 m > 2.2 m, impossibile. A terra: 9 × 0.96 = 8.64 m² ≤ 12 m², è possibile.","ref":"Modulo 3 · Problemi serie 1"},{"k":"num","q":"Una superficie di 600 m² è divisa in 3 zone uguali. Qual è la superficie di una zona?","n":200,"tol":0,"u":"m²","ex":"600 ÷ 3 = 200 m².","ref":"Modulo 2 · Calcolo delle superfici"},{"k":"multi","q":"Quali valori sono uguali a 1.5 m³?","good":["1’500 L","1’500 dm³","1’500’000 cm³"],"bad":["150 L","15’000 cm³"],"ex":"1.5 m³ = 1’500 dm³ = 1’500 L = 1’500’000 cm³.","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","s":"Il semirimorchio di un autoarticolato misura internamente 13.6 m di lunghezza, 2.45 m di larghezza e 2.7 m di altezza. Il pianificatore vuole il suo volume di carico.","q":"Qual è questo volume?","a":["89.96 m³","33.32 m³","18.75 m³","899.64 m³"],"ex":"13.6 × 2.45 × 2.7 = 89.96 m³ (circa 90 m³).","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"case","s":"Un cartone misura 60 cm × 40 cm × 50 cm. Il trasportatore fattura a volume e chiede il valore in m³.","q":"Quale volume comunica?","a":["0.12 m³","120 m³","1.2 m³","0.012 m³"],"ex":"Si converte prima in metri: 0.6 × 0.4 × 0.5 = 0.12 m³ (= 120’000 cm³).","ref":"Modulo 2 · Calcolo dei volumi"}]},{"code":"Mod. 2b","t":"Tempi, distanze e velocità","g":"Calcolare durate, orari d’arrivo, distanze e velocità","col":"amber","ic":"clock2","ch":[{"k":"num","q":"Quanti minuti fa 1 h 30?","n":90,"tol":0,"u":"min","ex":"1 h = 60 min. 60 + 30 = 90 min.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"qcm","q":"Quante ore (in numero decimale) fanno 90 minuti?","a":["1.5 h","1.3 h","1.9 h","0.9 h"],"ex":"Minuti → ore: ÷ 60. 90 ÷ 60 = 1.5 h.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"qcm","q":"A quale durata corrispondono 2.25 h?","a":["2 h 15","2 h 25","2 h 02","2 h 30"],"ex":"0.25 h × 60 = 15 min. 2.25 h = 2 h 15.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"num","q":"Quanti secondi fanno 4 min 30 s?","n":270,"tol":0,"u":"s","ex":"4 × 60 + 30 = 270 s.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"Un autista della Livrex parte dal deposito alle 08:45 per un giro previsto di 2 h 35.","q":"A che ora deve essere di ritorno?","a":["11:20","10:80","11:30","10:20"],"ex":"Ore: 8 + 2 = 10 h. Minuti: 45 + 35 = 80 min = 1 h 20. 10 h + 1 h 20 = 11:20.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"qcm","q":"Quale durata separa le 14:10 dalle 17:40?","a":["3 h 30","3 h 50","4 h 30","3 h 20"],"ex":"Dalle 14:10 alle 17:10: 3 h. Più 30 min: 3 h 30.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"Un magazziniere lavora dalle 07:30 alle 11:45, poi dalle 13:15 alle 17:00. Deve compilare il foglio ore.","q":"Quante ore ha lavorato?","a":["8 h","7 h 45","9 h 30","8 h 15"],"ex":"Mattino: 4 h 15. Pomeriggio: 3 h 45. Totale: 8 h.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"Un preparatore impiega 12 minuti per filmare ed etichettare una paletta. Deve prepararne 15 prima della partenza del camion.","q":"Quanto tempo gli serve?","a":["3 h","2 h 30","1 h 80","2 h 45"],"ex":"15 × 12 = 180 min = 3 h.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"num","q":"Un’operazione dura 3 min 20 s. Quante volte la si può fare in 1 ora?","n":18,"tol":0,"u":"volte","ex":"3 min 20 s = 200 s. 1 h = 3’600 s. 3’600 ÷ 200 = 18 volte.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"In una giornata di 8 h, un dipendente fa 40 min di pausa e passa 1 h in una riunione di squadra. Il capo vuole conoscere il suo tempo produttivo.","q":"Qual è il suo tempo produttivo?","a":["6 h 20","7 h","6 h 40","7 h 20"],"ex":"8 h − 40 min − 1 h = 6 h 20.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"Un giro inizia alle 06:10 e dura 3 h 45. L’autista poi mangia per 40 min, quindi riparte per 1 h 30 di consegne.","q":"A che ora finisce?","a":["12:05","11:05","11:25","10:35"],"ex":"06:10 + 3 h 45 = 09:55; + 40 min = 10:35; + 1 h 30 = 12:05. Il quiz del corso indica 11:05, è un errore.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"qcm","q":"Quale formula permette di calcolare una distanza?","a":["D = V × T","D = V ÷ T","D = T ÷ V","D = V + T"],"ex":"Distanza = velocità × tempo. Velocità = D ÷ T; tempo = D ÷ V.","ref":"Modulo 2 · Distanze e velocità"},{"k":"num","q":"Un tragitto di 360 km dura 4 h. Qual è la velocità media?","n":90,"tol":0,"u":"km/h","ex":"V = 360 ÷ 4 = 90 km/h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"num","q":"Un fattorino viaggia a 80 km/h per 45 minuti. Che distanza percorre?","n":60,"tol":0,"u":"km","ex":"45 min = 0.75 h. 80 × 0.75 = 60 km.","ref":"Modulo 2 · Distanze e velocità"},{"k":"num","q":"Quante ore servono per fare 200 km a 100 km/h?","n":2,"tol":0,"u":"h","ex":"T = 200 ÷ 100 = 2 h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"Un fattorino guida prima 60 minuti a 45 km/h in città, poi 90 minuti a 60 km/h sulla strada cantonale.","q":"Che distanza ha percorso?","a":["135 km","127.5 km","105 km","157.5 km"],"ex":"45 × 1 = 45 km; 60 × 1.5 = 90 km. Totale: 135 km. Il quiz del corso indica 127.5 km, è un errore.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"Un camion percorre 180 km in 2 h, fa una pausa di 30 min, poi viaggia ancora per 120 km a 60 km/h.","q":"Qual è la durata totale?","a":["4 h 30","5 h 30","4 h 00","5 h 00"],"ex":"2 h + 30 min + (120 ÷ 60 = 2 h) = 4 h 30. Il quiz del corso indica 5 h 30, è un errore.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"Un autista parte alle 07:40 per un tragitto di 192 km. Viaggia a una velocità media di 80 km/h, senza pause.","q":"A che ora arriva?","a":["10:04","10:32","09:52","10:24"],"ex":"T = 192 ÷ 80 = 2.4 h = 2 h 24 (0.4 × 60 = 24 min). 07:40 + 2 h 24 = 10:04.","ref":"Modulo 2 · Distanze e velocità"},{"k":"qcm","q":"A quante ore in numero decimale corrisponde 1 h 20 min?","a":["1.33 h","1.20 h","1.50 h","1.25 h"],"ex":"20 min ÷ 60 = 0.33 h. 1 h 20 = 1.33 h, non 1.20 h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"qcm","q":"Un fattorino impiega 1 h 20 per fare 96 km. Qual è la sua velocità media?","a":["72 km/h","80 km/h","76.8 km/h","120 km/h"],"ex":"1 h 20 = 4/3 h. V = 96 ÷ 4/3 = 96 × 3 ÷ 4 = 72 km/h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"In magazzino si cronometra un carrello elevatore: percorre 600 m in 3 minuti. Il responsabile della sicurezza vuole la sua velocità in km/h.","q":"Qual è la velocità del carrello?","a":["12 km/h","200 km/h","20 km/h","1.8 km/h"],"ex":"600 m = 0.6 km ; 3 min = 0.05 h. V = 0.6 ÷ 0.05 = 12 km/h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"match","q":"Abbini ogni conversione all’operazione da fare.","p":[["min → h","÷ 60"],["h → min","× 60"],["m/s → km/h","× 3.6"],["km → m","× 1’000"]],"ex":"Tabella delle conversioni utili del corso.","ref":"Modulo 2 · Distanze e velocità"},{"k":"order","q":"Metta in ordine il metodo per sommare due durate.","a":["Sommare le ore tra loro","Sommare i minuti tra loro","Convertire in ore i minuti oltre 60","Scrivere il risultato in h e min"],"ex":"1 h 45 + 2 h 35 = 3 h 80 min = 4 h 20.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"sort","q":"Classifichi: durata oppure ora (momento della giornata)?","c":["Durata","Ora"],"it":[["Partenza alle 07:40",1],["Tragitto di 2 h 24",0],["Pausa di 30 min",0],["Arrivo alle 10:04",1],["Giro di 5 h 40",0],["Fine servizio alle 17:00",1]],"ex":"Un’ora indica un momento; una durata indica quanto tempo passa.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"odd","q":"Trovi l’intruso: quale di queste durate NON è uguale a 2.5 h?","a":["2 h 50","2 h 30","150 min","9’000 s"],"ex":"2.5 h = 2 h 30 = 150 min = 9’000 s. 2 h 50 = 2.83 h.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"tf","q":"2 h 30 si scrive 2.30 h in numero decimale.","v":false,"ex":"Falso: 30 min = 0.5 h, quindi 2 h 30 = 2.5 h. Un’ora conta 60 minuti, non 100.","ref":"Modulo 2 · Tempo di lavoro"},{"k":"case","s":"Un trattore da magazzino viaggia a 4.5 km/h. Il conducente lo guida per 40 minuti in tutto durante il suo giro di approvvigionamento.","q":"Che distanza percorre?","a":["3 km","180 km","1.8 km","4.5 km"],"ex":"40 min = 2/3 h. 4.5 × 2/3 = 3 km.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"Un camion percorre 100 km a 50 km/h, poi 60 km a 80 km/h, poi 90 km a 60 km/h. Il pianificatore calcola il tempo di guida.","q":"Qual è il tempo di guida totale?","a":["4 h 15","4 h","3 h 45","4 h 30"],"ex":"100 ÷ 50 = 2 h; 60 ÷ 80 = 45 min; 90 ÷ 60 = 1 h 30. Totale: 4 h 15.","ref":"Modulo 2 · Distanze e velocità"},{"k":"tf","q":"Per convertire una velocità da m/s a km/h si moltiplica per 3.6.","v":true,"ex":"Vero: 1 m/s = 3.6 km/h (3’600 s in 1 h, 1’000 m in 1 km).","ref":"Modulo 2 · Distanze e velocità"},{"k":"num","q":"Converta 10 m/s in km/h.","n":36,"tol":0,"u":"km/h","ex":"10 × 3.6 = 36 km/h.","ref":"Modulo 2 · Distanze e velocità"},{"k":"case","s":"Un fattorino deve essere da un cliente alle 14:00. Il tragitto è di 150 km e viaggia in media a 75 km/h, senza pause.","q":"A che ora deve partire al più tardi?","a":["12:00","12:30","11:45","13:15"],"ex":"T = 150 ÷ 75 = 2 h. 14:00 − 2 h = 12:00.","ref":"Modulo 2 · Distanze e velocità"}]},{"code":"Mod. 3","t":"Problemi in più fasi","g":"Risolvere un problema logistico in più fasi e verificare che il risultato sia realistico","col":"emerald","ic":"steps","ch":[{"k":"order","q":"Metta in ordine il metodo per risolvere un problema in più fasi.","a":["Leggere attentamente la consegna","Individuare i dati e convertire le unità","Calcolare passo per passo","Verificare la coerenza del risultato"],"ex":"Metodo del corso: leggere, scomporre, calcolare passo per passo, poi verificare che la risposta sia realistica.","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Nove palette devono essere stoccate a blocco, impilate 2 a 2. Ogni pila occupa un’ubicazione a terra.","q":"Quante ubicazioni servono?","a":["5 ubicazioni","4 ubicazioni","4.5 ubicazioni","9 ubicazioni"],"ex":"9 ÷ 2 = 4.5 → si arrotonda per eccesso: 4 pile da 2 + 1 paletta singola = 5 ubicazioni.","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Un ordine di 180 colli deve essere palettizzato. Si mettono al massimo 24 colli per paletta.","q":"Quante palette bisogna preparare?","a":["8 palette","7 palette","7.5 palette","9 palette"],"ex":"180 ÷ 24 = 7.5 → si arrotonda per eccesso: 8 palette (l’ultima non è completa).","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Un furgone ha un carico utile di 1.5 t. Vi si caricano 480 kg di cartoni, 0.65 t di taniche e 3’500 hg di sacchi.","q":"Il carico utile è rispettato?","a":["Sì: 1’480 kg, restano 20 kg","No: 1’480 kg superano 1.5 t","No: 4’630 kg superano 1.5 t","Sì: 1’130 kg, restano 370 kg"],"ex":"Tutto in kg: 480 + 650 + 350 = 1’480 kg ≤ 1’500 kg. Restano 20 kg.","ref":"Modulo 3 · Problemi serie 2"},{"k":"case","s":"Uno scaffale sopporta 1’000 kg. Si vogliono stoccare 20 cartoni da 18 kg, 15 cartoni da 25 kg e 8 cartoni da 40 kg.","q":"Che cosa constata?","a":["Sovraccarico di 55 kg","Restano 55 kg di margine","Sovraccarico di 83 kg","Il carico è esattamente 1’000 kg"],"ex":"360 + 375 + 320 = 1’055 kg > 1’000 kg: sovraccarico di 55 kg. Bisogna spostare dei cartoni.","ref":"Modulo 3 · Problemi serie 2"},{"k":"num","img":"tournee","q":"Un giro serve 5 clienti: 22 km, 13 km, 8 km, 14 km e 18 km tra le fermate, poi 25 km di ritorno diretto al deposito. Distanza totale?","n":100,"tol":0,"u":"km","ex":"Andata: 22 + 13 + 8 + 14 + 18 = 75 km. Con il ritorno: 75 + 25 = 100 km.","ref":"Modulo 3 · Problemi serie 2"},{"k":"case","s":"Un ordine di scaffali costa CHF 4’500.00. Il fornitore concede l’8 % di sconto e fattura CHF 95.00 di consegna.","q":"Qual è l’importo della fattura?","a":["CHF 4’235.00","CHF 4’227.40","CHF 4’140.00","CHF 4’955.00"],"ex":"4’500 × 0.92 = 4’140; 4’140 + 95 = CHF 4’235.00. Lo sconto non si applica alle spese di consegna.","ref":"Modulo 3 · Problemi serie 2"},{"k":"case","s":"Un preparatore deve preparare 5 colli di tipo A (7 min ciascuno), 8 di tipo B (12 min) e 4 di tipo C (9 min).","q":"Quanto tempo gli serve in tutto?","a":["2 h 47","2 h 30","1 h 67","3 h 07"],"ex":"35 + 96 + 36 = 167 min = 2 h 47.","ref":"Modulo 3 · Problemi serie 3"},{"k":"case","s":"Fattura 12 pezzi a CHF 48.00 IVA esclusa. Va aggiunta l’IVA all’aliquota normale (8.1 %).","q":"Qual è il totale IVA inclusa?","a":["CHF 622.66","CHF 620.35","CHF 584.10","CHF 529.34"],"ex":"12 × 48 = CHF 576.00 IVA esclusa. 576 × 1.081 = CHF 622.66. Non nel materiale del corso: il corso calcola con il 7.7 %, aliquota in vigore fino a fine 2023.","ref":"Modulo 3 · Problemi serie 3"},{"k":"case","s":"Una paletta di 720 kg deve essere scaricata e spostata a carichi più piccoli con un carrello di movimentazione che porta al massimo 300 kg.","q":"Quanti viaggi servono?","a":["3 viaggi","2 viaggi","2.4 viaggi","4 viaggi"],"ex":"720 ÷ 300 = 2.4 → si arrotonda per eccesso: 3 viaggi.","ref":"Modulo 3 · Problemi serie 4"},{"k":"case","s":"Un ordine comprende 4 cartoni da 5 kg, 6 cartoni da 7.5 kg e 6 cartoni da 2.8 kg. Deve andare su un ripiano che sopporta 100 kg.","q":"Si può stoccare su questo ripiano?","a":["Sì: 81.8 kg, margine di 18.2 kg","No: 81.8 kg superano 100 kg","Sì: solo 15.3 kg","No: 109.4 kg superano 100 kg"],"ex":"20 + 45 + 16.8 = 81.8 kg ≤ 100 kg. Margine: 18.2 kg.","ref":"Modulo 3 · Problemi serie 4"},{"k":"case","s":"Un autista dispone di 6 h per un giro di 240 km a 80 km/h di media, con 12 consegne da 10 min e 3 pause da 15 min.","q":"Rispetta il termine?","a":["Sì: 5 h 45, margine di 15 min","No: 6 h 15, ritardo di 15 min","Sì: solo 3 h di strada","No: 6 h 45, ritardo di 45 min"],"ex":"Strada: 240 ÷ 80 = 3 h. Consegne: 2 h. Pause: 45 min. Totale: 5 h 45 ≤ 6 h.","ref":"Modulo 3 · Problemi serie 4"},{"k":"case","img":"zone","s":"Una zona di 6 m × 4 m e alta 2.5 m deve accogliere palette EUR alte 1.5 m. Il capo chiede la capacità della zona.","q":"Quante palette può accogliere la zona?","a":["25 palette, su 1 solo strato","50 palette, su 2 strati","24 palette, su 1 solo strato","41 palette, su 2 strati"],"ex":"A terra: 5 × 5 = 25 palette. In altezza: 2 × 1.5 = 3 m > 2.5 m, quindi un solo strato.","ref":"Modulo 3 · Problemi serie 3"},{"k":"tf","q":"Per calcolare un numero di viaggi si arrotonda sempre all’intero superiore.","v":true,"ex":"Vero: con 2.4 viaggi resta un carico da trasportare, quindi serve un 3° viaggio.","ref":"Modulo 3 · Problemi serie 4"},{"k":"tf","q":"Per sapere quanti fusti interi entrano in uno spazio si arrotonda all’intero superiore.","v":false,"ex":"Falso: il 12° fusto non ci starebbe. Si arrotonda per difetto quando si cerca ciò che «ci sta».","ref":"Modulo 2 · Calcolo dei volumi"},{"k":"sort","q":"Bisogna arrotondare per eccesso o per difetto?","c":["Per eccesso","Per difetto"],"it":[["Numero di viaggi necessari",0],["Palette da preparare per 180 colli",0],["Fusti che stanno in 2.5 m³",1],["Colli preparati in 50 min",1],["Persone da assumere",0],["Cartoni su un ripiano con limite di carico",1]],"ex":"Ciò che serve per fare tutto: per eccesso. Ciò che ci sta o che è finito: per difetto.","ref":"Modulo 3 · Problemi serie 4"},{"k":"match","q":"Abbini ogni grandezza alla sua formula.","p":[["Prezzo dopo lo sconto","Prezzo × (1 − tasso)"],["Prezzo IVA inclusa","Prezzo IVA esclusa × (1 + aliquota IVA)"],["Capacità residua","Capacità max − massa utilizzata"],["Numero di viaggi","Massa totale ÷ capacità"]],"ex":"Formule delle serie di problemi 2, 3 e 4.","ref":"Modulo 3 · Problemi serie 2"},{"k":"odd","q":"Trovi l’intruso: quale abitudine NON fa parte di un buon metodo?","a":["Arrotondare ogni calcolo intermedio","Individuare i dati utili","Mettere i valori nella stessa unità","Verificare se la risposta è realistica"],"ex":"Si mantengono i valori esatti durante il calcolo e si arrotonda solo il risultato finale.","ref":"Modulo 3 · Problemi serie 1"},{"k":"num","q":"Bisogna consegnare 4’250 kg con un furgone da 1’200 kg di carico utile. Quanti viaggi servono?","n":4,"tol":0,"u":"viaggi","ex":"4’250 ÷ 1’200 = 3.54 → si arrotonda per eccesso: 4 viaggi.","ref":"Modulo 3 · Problemi serie 4"},{"k":"case","s":"Si vogliono appoggiare a terra 8 palette EUR (0.96 m² ciascuna) in un angolo libero della banchina di 7.5 m².","q":"L’angolo è abbastanza grande?","a":["No: servono 7.68 m²","Sì: servono 7.2 m²","Sì: restano 0.18 m²","No: servono 9.6 m²"],"ex":"8 × 0.96 = 7.68 m² > 7.5 m²: mancano 0.18 m².","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Una paletta carica fa 1.6 m³ per 0.96 m² a terra. Il magazziniere vorrebbe impilarne due sotto un soffitto di 2.2 m.","q":"È possibile?","a":["No: 2 × 1.67 m = 3.33 m","Sì: 1.67 m < 2.2 m","Sì: 1.6 m³ < 2.2 m","No: 2 × 0.96 m = 1.92 m"],"ex":"Altezza = 1.6 ÷ 0.96 ≈ 1.67 m. Due palette: circa 3.33 m > 2.2 m.","ref":"Modulo 3 · Problemi serie 1"},{"k":"multi","q":"Quali controlli di coerenza sono utili alla fine di un problema?","good":["Un numero di palette è un numero intero","La massa non supera il carico utile","Le unità erano le stesse prima di sommare"],"bad":["Il risultato ha il maggior numero di decimali possibile","Il risultato è più grande di tutti i dati"],"ex":"Il risultato deve essere realistico e rispettare i vincoli del terreno.","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Un collega somma i suoi tempi di preparazione: 35 + 96 + 36 = 167 min. Scrive «1 h 67» sul foglio di lavoro.","q":"Che cosa corregge?","a":["167 min = 2 h 47","167 min = 1.67 h","Niente: 1 h 67 è giusto","167 min = 16 h 7"],"ex":"167 ÷ 60 = 2 resto 47: 2 h 47. Un’ora conta 60 minuti.","ref":"Modulo 3 · Problemi serie 3"},{"k":"case","s":"Un magazzino conta 3 zone da 500 m². I corridoi e le zone di sicurezza occupano il 20 % della superficie. Il resto serve a stoccare palette EUR a terra.","q":"Quante palette al massimo, a terra?","a":["1’250 palette","1’562 palette","1’200 palette","1’440 palette"],"ex":"Totale: 1’500 m². Stoccaggio: 1’500 × 0.8 = 1’200 m². 1’200 ÷ 0.96 = 1’250 palette (massimo teorico).","ref":"Modulo 3 · Problemi serie 1"},{"k":"case","s":"Fattura 150 cartoni a CHF 3.20 IVA esclusa. Il cliente ha diritto al 5 % di sconto, poi si aggiunge l’IVA dell’8.1 %.","q":"Qual è il totale IVA inclusa?","a":["CHF 492.94","CHF 518.88","CHF 456.00","CHF 494.88"],"ex":"150 × 3.20 = 480; sconto: 480 × 0.95 = 456; IVA: 456 × 1.081 = CHF 492.94.","ref":"Modulo 3 · Problemi serie 3"},{"k":"num","q":"Un dipendente prepara solo colli di tipo C (9 min ciascuno). Quanti ne prepara in 90 min?","n":10,"tol":0,"u":"colli","ex":"90 ÷ 9 = 10 colli.","ref":"Modulo 3 · Problemi serie 3"},{"k":"case","s":"Partenza dal deposito alle 07:30. Il giro comprende 2 h 10 di strada, 7 consegne da 12 min e una pausa di 20 min.","q":"A che ora rientra l’autista?","a":["11:24","10:04","11:44","10:24"],"ex":"7 × 12 = 84 min. 130 + 84 + 20 = 234 min = 3 h 54. 07:30 + 3 h 54 = 11:24.","ref":"Modulo 3 · Problemi serie 4"},{"k":"qcm","q":"Una fattura comprende uno sconto e spese di trasporto. In che ordine si calcola?","a":["Prima lo sconto, poi le spese","Prima le spese, poi lo sconto","Sconto solo sulle spese","L’ordine non cambia mai nulla"],"ex":"Lo sconto riguarda la merce. Poi si aggiungono le spese (regola della serie 2 del corso).","ref":"Modulo 3 · Problemi serie 2"}]}];
window.LEVELS = [[0,"Stagista"],[150,"Apprendista in logistica"],[400,"Impiegato/a in logistica in formazione"],[800,"Impiegato/a in logistica AFC"],[1300,"Referente calcolo di base"],[2000,"Esperto/a di misure e conversioni"],[3000,"Formatore/trice in logistica"]];
